import{_ as t,o as i,c as a,a4 as o}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"登录日志与管理员审计日志存储决策","description":"","frontmatter":{"title":"登录日志与管理员审计日志存储决策","date":"2026-08-26T00:00:00.000Z"},"headers":[],"relativePath":"posts/登录日志与管理员审计日志存储决策.md","filePath":"posts/登录日志与管理员审计日志存储决策.md"}'),r={name:"posts/登录日志与管理员审计日志存储决策.md"};function s(e,l,n,d,g,_){return i(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="登录日志与管理员审计日志存储决策" tabindex="-1">登录日志与管理员审计日志存储决策 <a class="header-anchor" href="#登录日志与管理员审计日志存储决策" aria-label="Permalink to &quot;登录日志与管理员审计日志存储决策&quot;">​</a></h1><blockquote><p>日期：2026-08-26<br> 上下文：mybilibili 项目架构讨论<br> 目标环境：k3s 轻量部署 + 弱设备（盒子/老电脑） + 不深入复杂运维</p></blockquote><h2 id="_1-背景与问题" tabindex="-1">1. 背景与问题 <a class="header-anchor" href="#_1-背景与问题" aria-label="Permalink to &quot;1. 背景与问题&quot;">​</a></h2><p>项目需要支持：</p><ul><li>用户个人中心查看自己的登录历史（login logs）</li><li>管理员后台查看和搜索用户登录日志 + 管理员操作审计（audit logs）</li><li>AI 用量统计日志（ai_usage_logs）</li></ul><p>核心问题：</p><ul><li>这种<strong>业务审计数据</strong>应该写到哪里？</li><li>和 observability 日志（Loki）有什么区别？</li><li>NATS / Kafka 能不能当日志数据库用？</li><li>在只玩 k3s、不想深玩运维的情况下，最简单的标准做法是什么？</li></ul><h2 id="_2-关键概念区分-本次讨论核心" tabindex="-1">2. 关键概念区分（本次讨论核心） <a class="header-anchor" href="#_2-关键概念区分-本次讨论核心" aria-label="Permalink to &quot;2. 关键概念区分（本次讨论核心）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>例子</th><th>查询特点</th><th>推荐存储</th></tr></thead><tbody><tr><td><strong>应用运行日志</strong></td><td>debug、error、请求 trace</td><td>全文搜索、标签过滤</td><td>Loki</td></tr><tr><td><strong>K8s 平台审计</strong></td><td>API Server 操作</td><td>集群安全合规</td><td>专用 SIEM / Loki</td></tr><tr><td><strong>业务审计日志</strong></td><td>用户登录、管理员改权限、AI 调用</td><td>结构化过滤、分页、关联</td><td><strong>Postgres</strong></td></tr></tbody></table><p><strong>业务审计日志特点</strong>：</p><ul><li>需要精确结构化查询（按 user_id、按时间范围、按操作类型）</li><li>前端需要直接展示和分页</li><li>需要和用户表、管理员表关联</li><li>属于<strong>业务数据</strong>，而非纯运维日志</li></ul><h2 id="_3-各方案评估-针对本项目" tabindex="-1">3. 各方案评估（针对本项目） <a class="header-anchor" href="#_3-各方案评估-针对本项目" aria-label="Permalink to &quot;3. 各方案评估（针对本项目）&quot;">​</a></h2><h3 id="_3-1-postgres-主库" tabindex="-1">3.1 Postgres（主库） <a class="header-anchor" href="#_3-1-postgres-主库" aria-label="Permalink to &quot;3.1 Postgres（主库）&quot;">​</a></h3><ul><li><strong>优点</strong>： <ul><li>已建表（login_logs、audit_logs、ai_usage_logs）</li><li>查询能力强（索引、分页、JOIN）</li><li>事务一致性好</li><li>前后端已经打通</li></ul></li><li><strong>缺点</strong>：需要管理增长（已通过分区解决）</li><li><strong>结论</strong>：<strong>最适合</strong></li></ul><h3 id="_3-2-loki" tabindex="-1">3.2 Loki <a class="header-anchor" href="#_3-2-loki" aria-label="Permalink to &quot;3.2 Loki&quot;">​</a></h3><ul><li>定位是应用 stdout 日志聚合（云原生标准）</li><li>查询结构化业务数据不友好</li><li>UI 集成成本高</li><li><strong>结论</strong>：不推荐用于登录/审计日志</li></ul><h3 id="_3-3-nats-jetstream" tabindex="-1">3.3 NATS JetStream <a class="header-anchor" href="#_3-3-nats-jetstream" aria-label="Permalink to &quot;3.3 NATS JetStream&quot;">​</a></h3><ul><li>可以作为 append-only 事件流（类似轻量日志）</li><li>适合短期 retention 和异步处理</li><li>查询能力很弱（主要是顺序消费）</li><li><strong>结论</strong>：可作为<strong>辅助事件通道</strong>，不能当主存储</li></ul><h3 id="_3-4-kafka" tabindex="-1">3.4 Kafka <a class="header-anchor" href="#_3-4-kafka" aria-label="Permalink to &quot;3.4 Kafka&quot;">​</a></h3><ul><li>功能强大，但资源重（单 broker 常需几百 MB~GB 内存）</li><li>运维复杂度高</li><li>与项目“轻量 + 弱设备”目标冲突</li><li><strong>结论</strong>：不推荐</li></ul><h2 id="_4-k3s-轻量云原生标准做法-不深玩运维版" tabindex="-1">4. k3s 轻量云原生标准做法（不深玩运维版） <a class="header-anchor" href="#_4-k3s-轻量云原生标准做法-不深玩运维版" aria-label="Permalink to &quot;4. k3s 轻量云原生标准做法（不深玩运维版）&quot;">​</a></h2><p>标准分层（CNCF 推荐简化版）：</p><ol><li><strong>应用日志</strong> → stdout → Loki（未来）</li><li><strong>业务审计日志</strong>（登录 + 管理员操作） → 主数据库（Postgres）</li><li><strong>异步事件</strong> → NATS JetStream</li><li><strong>K8s 自身审计</strong>（如果需要） → 单独配置 API Server audit policy（可选，运维层面）</li></ol><p><strong>核心原则</strong>：</p><ul><li>业务可查询的历史记录 → 关系型数据库</li><li>可观测性日志 → Loki</li><li>事件解耦 → NATS</li></ul><h2 id="_5-最终决策" tabindex="-1">5. 最终决策 <a class="header-anchor" href="#_5-最终决策" aria-label="Permalink to &quot;5. 最终决策&quot;">​</a></h2><p><strong>保持当前实现</strong>：</p><ul><li><strong>用户登录日志</strong> 和 <strong>管理员操作日志</strong> 继续放在 <strong>Postgres</strong></li><li>使用时间范围分区（RANGE BY month）</li><li>写入保持简单：登录成功和敏感操作直接 INSERT</li><li>可选扩展：关键操作同时 publish 到 NATS（作为事件源）</li></ul><p><strong>已实施内容</strong>：</p><ul><li>sql/007_user_extend.sql、009_admin.sql、013_ai_support.sql 定义表</li><li>sql/025_partition_log_tables.sql（分区迁移，已创建）</li><li>sql/999_go_tables.sql 已同步分区定义</li><li>前端 Admin 和 Web 个人中心已支持查询</li><li>文档记录：docs/decisions/01-架构决策记录.md (ADR-5)</li></ul><h2 id="_6-保留与清理策略建议" tabindex="-1">6. 保留与清理策略建议 <a class="header-anchor" href="#_6-保留与清理策略建议" aria-label="Permalink to &quot;6. 保留与清理策略建议&quot;">​</a></h2><ul><li>login_logs：保留最近 6 个月</li><li>audit_logs：保留最近 12 个月</li><li>ai_usage_logs：保留最近 3-6 个月</li></ul><p>实现方式（简单）：</p><ul><li>按月分区</li><li>定期执行 <code>DROP TABLE login_logs_y202x_mxx;</code></li></ul><h2 id="_7-为什么这个决定符合项目约束" tabindex="-1">7. 为什么这个决定符合项目约束 <a class="header-anchor" href="#_7-为什么这个决定符合项目约束" aria-label="Permalink to &quot;7. 为什么这个决定符合项目约束&quot;">​</a></h2><ul><li>符合弱设备 + k3s 轻量目标（不需要额外重组件）</li><li>最小运维负担（复用现有 Postgres）</li><li>查询需求直接满足（无需额外开发搜索层）</li><li>与项目早期技术选型一致（08-technology-selection.md、02-logging-strategy.md）</li></ul><h2 id="_8-后续建议-保持简单优先" tabindex="-1">8. 后续建议（保持简单优先） <a class="header-anchor" href="#_8-后续建议-保持简单优先" aria-label="Permalink to &quot;8. 后续建议（保持简单优先）&quot;">​</a></h2><ul><li>不要把登录/审计日志混到 Loki</li><li>NATS 主要用于事件异步和广播（弹幕、任务、索引同步等）</li><li>如果未来需要事件 sourcing，可让 NATS 作为事件源，消费者再写 PG</li><li>保持当前表结构 + 分区即可满足需求</li></ul><hr><p><strong>结论</strong>：<br> 单纯的用户登录日志和管理员操作日志，在只玩 k3s、不深运维的情况下，<strong>放在 Postgres + 时间分区</strong> 是最正确、最简单的选择。已按此方向实施并记录。</p><p>文档位置：<code>/home/a1/文档/登录日志与管理员审计日志存储决策.md</code></p>',41)])])}const c=t(r,[["render",s]]);export{u as __pageData,c as default};
